"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[53309],{28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var a=n(96540);const i={},o=a.createContext(i);function s(e){const t=a.useContext(o);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}},79240:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"qiangguo/newnationalism","title":"","description":"For the battle-hardened Mr. He Xin, of course he knows the importance of a name and a brand, so flying the banner of \\"New Nationalism\\" is perfectly normal. But you should at least give the sign a better coat of paint. Slapping \\"nationalism\\" together -- even emphasizing that it\'s \\"new\\" in front -- is nothing but the Emperor\'s New Clothes. Just because your name is He Xin (He meaning \\"what\\" and Xin meaning \\"new\\"), and the banner also claims to be new, does that make it new? Self-deception, nothing more. The substance of New Nationalism is nothing but a contemporary masturbatory fantasy of the Prussian Empire that Hegel dreamed of as the real-world incarnation of the Absolute Idea. Mr. He Xin, \\"New Nationalism\\" -- what\'s new about it?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/newnationalism.md","sourceDirName":"qiangguo","slug":"/qiangguo/newnationalism","permalink":"/qiangguo/newnationalism","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"newnationalism","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u4f55\u65b0\u4e4b\u201c\u75c5\u201d\u53ca\u76f8\u5e94\u4e4b\u201c\u836f\u201d\uff08\u4e25\u8083\u4e4b\u8bba\uff0c\u8bf7\u653e\u884c\uff09","permalink":"/qiangguo/hexinproblemandsolution"},"next":{"title":"\u4f55\u65b0\u5148\u751f\u7b49\uff0c\u4f60\u4eec\u90a3\u4e9b\u6240\u8c13\u8054\u65e5\u53cd\u7f8e\u7684\u998a\u4e3b\u610f\u8be5\u6b47\u4e86","permalink":"/qiangguo/unitjapanantiusa"}}');var i=n(74848),o=n(28453);const s={id:"newnationalism",title:"",hide_table_of_contents:!0},r='Mr. He Xin, "New Nationalism" -- What\'s New About It?',h={},l=[];function u(e){const t={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"mr-he-xin-new-nationalism----whats-new-about-it",children:'Mr. He Xin, "New Nationalism" -- What\'s New About It?'})}),"\n",(0,i.jsx)(t.p,{children:'For the battle-hardened Mr. He Xin, of course he knows the importance of a name and a brand, so flying the banner of "New Nationalism" is perfectly normal. But you should at least give the sign a better coat of paint. Slapping "nationalism" together -- even emphasizing that it\'s "new" in front -- is nothing but the Emperor\'s New Clothes. Just because your name is He Xin (He meaning "what" and Xin meaning "new"), and the banner also claims to be new, does that make it new? Self-deception, nothing more. The substance of New Nationalism is nothing but a contemporary masturbatory fantasy of the Prussian Empire that Hegel dreamed of as the real-world incarnation of the Absolute Idea. Mr. He Xin, "New Nationalism" -- what\'s new about it?'}),"\n",(0,i.jsx)(t.p,{children:'Setting aside such logically confused and self-contradictory proclamations as "Nationalism must rely on universal indoctrination of the entire populace! Make it a natural belief!" and "The nation is a belief. Its justice requires no logical proof, no sufficient reason" -- let us simply note that this gentleman uses reasoning like "after the death of Confucius, Confucianism split into eight schools" to argue that Marxism cannot serve as a governing philosophy. From this alone, the extent of his ignorance is clear. He thinks his New Nationalism has but a single creed and therefore won\'t "split into eight." But this gentleman who claims deep familiarity with the classics surely knows this line: "The Way gives birth to one, one gives birth to two, two gives birth to three, three gives birth to all things." And his "one" is already so fragmented, and his "Way" so wayless -- even a wayless wayfarer is nothing but wreckage. This gentleman who claims to lean toward Buddhism -- does he not know that dharmas are fundamentally unborn?'}),"\n",(0,i.jsx)(t.p,{children:'This gentleman prattles on about "There is an extremely profound viewpoint in Hegel\'s political philosophy, one that has never been properly understood -- he said: The state is not built on material things, but on spirit and thought." Pray tell, where does spirit and thought come from? Does practicing your New Nationalism Grand Method produce them? Typical Hegelian feverish drivel.'}),"\n",(0,i.jsx)(t.p,{children:"As I have said before, Mr. He Xin has never gotten past the Hegel hurdle. Even setting aside his other dealings, from a purely academic standpoint -- doesn't Mr. He Xin love textual research the most? Why not take that New Nationalism back to the oven and bake it a few more rounds. Crispy on the outside and tender on the inside is impossible, but at least the presentation would be somewhat better than its current pitiful state."})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);